getListProduct:
query getListProduct(
    $page: Int
    $perPage: Int
    $filter: ListProductFilterInput
  ) {
    listProduct(
      query: { pagination: { page: $page, perPage: $perPage }, filter: $filter }
    ) {
      ... on ListProductRes {
        currentPage
        items {
          brand {
            status
          }
          sni {
            status
          }
          tkdn {
            status
          }
          categoryType
          category {
            id
            isActive
            name
          }
          id
          images {
            id
            imageUrl
          }
          name
          prices {
            minPrice
            maxPrice
            minPriceWithTax
            maxPriceWithTax
            productWholesalePrices {
              price
            }
            selectedRegionPrice {
              price
              regionCode
            }
          }
          slug
          status
          stockAccumulation
          type
          username
          variants {
            id
            imageUrl
            isActive
            optionValues
            options
            price
            sku
            sortOrder
            stock
          }
          tax {
            ppnBmPercentage
            ppnPercentage
          }
          labels
          preOrder {
            sla
          }
          curationType
          curation {
            id
            productId
            status
            type
            details {
              curatorRoleId
              curatorRoleName
              description
              id
              notes
              productCurationId
              status
              rejectReasons {
                curationType
                description
                enum
                id
                reason
              }
            }
          }
          hasDecimalQuantity
        }
        lastPage
        perPage
        total
      }
      ... on GenericError {
        __typename
        code
        message
        reqId
      }
    }
  }

